package org.sleepwell.app;
import android.app.*;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;
/** Independent explicit Home Assistant connection, disabled by default. */
public final class PirSettingsActivity extends Activity implements PirSettingsJob.Observer {
 private PirSettingsJob job;private EditText endpoint,token,entity;private Switch enabled;
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();job=retained instanceof PirSettingsJob?(PirSettingsJob)retained:new PirSettingsJob(getApplicationContext());job.observe(this);}
 @Override public Object onRetainNonConfigurationInstance(){read();return job;}
 public void changed(){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"External PIR input",this::finish);Design.space(body,12);if(job.draft==null){Design.text(body,"Opening saved connection…",14,400,Design.MUTED);return;}PirConfig draft=job.draft;Design.text(body,"Home Assistant motion / occupancy",18,600,Design.INK);Design.space(body,8);Design.text(body,"Requires your own Home Assistant server and PIR sensor. Read-only HTTPS; no device commands. Credentials are separate from the bedroom light connection.",13,400,Design.MUTED);endpoint=field(body,"PIR server HTTPS address",draft.endpoint,false);token=field(body,"PIR long-lived access token",draft.token,true);entity=field(body,"PIR binary_sensor entity",draft.entity,false);enabled=Design.toggle(body,"Record with manual nights","No automatic or recurring PIR capture. Read successfully before enabling Save.",draft.enabled,on->{});Design.space(body,12);Design.text(body,"The hub is polled about every 15 seconds while tracking is active. Each point is a hub snapshot, not a fresh hardware reading. Old unchanged on/off states can be legitimate. Unknown states and failed reads stay blank; no sleep stages or body movement are inferred.",13,400,Design.MUTED);if(job.reading!=null){Design.space(body,10);Design.text(body,job.reading.quality+" · "+job.reading.deviceClass+" · request "+job.reading.latency+" ms",13,500,Design.BROWN);Design.text(body,job.reading.age==null?"Hub update age unavailable":("Hub last_updated age: "+RecordUi.duration(job.reading.age)+" (not hardware freshness)"),12,400,Design.MUTED);}if(!job.message.isEmpty()){Design.space(body,10);Design.text(body,job.message,13,500,Design.BROWN);}Design.button(body,"Test / read PIR state",false,()->act(false));Design.button(body,"Disconnect PIR",false,job::disconnect);if(job.busy)RecordUi.enabled(body,false);LinearLayout footer=RecordUi.footer(body);Design.button(footer,job.busy?"Please wait…":"Save external PIR",true,()->act(true)).setEnabled(!job.busy);}
 private EditText field(LinearLayout body,String label,String value,boolean secret){Design.space(body,10);Design.text(body,label,13,500,Design.INK);EditText input=new EditText(this);input.setSingleLine(true);input.setTextSize(14);input.setTypeface(Design.font(this,400));input.setTextColor(Design.INK);input.setMinHeight(Design.dp(this,48));input.setPadding(Design.dp(this,12),Design.dp(this,8),Design.dp(this,12),Design.dp(this,8));input.setBackground(Design.shape(this,Design.SOFT,12));input.setContentDescription(label);input.setInputType(InputType.TYPE_CLASS_TEXT|(secret?InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS));input.setSaveEnabled(false);input.setText(value);body.addView(input,new LinearLayout.LayoutParams(-1,-2));return input;}
 private void read(){if(job.draft!=null&&endpoint!=null&&!job.busy){PirConfig old=job.draft;job.draft=new PirConfig(endpoint.getText().toString().trim(),token.getText().toString(),entity.getText().toString().trim(),old.deviceClass,enabled.isChecked(),old.revision);}}
 private void act(boolean save){if(job.busy)return;read();try{if(save)job.save(job.draft);else job.check(job.draft);}catch(IllegalArgumentException invalid){job.message=invalid.getMessage();changed();}}
 @Override protected void onPause(){read();job.cancelTest();super.onPause();}
 @Override protected void onDestroy(){job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
